// PORT: Go `nonBinaryUnicodeProperties[name]`. A missing key gives "", the
// Go zero value.
pub fn non_binary_unicode_property(name: &str) -> &'static str {
    NON_BINARY_UNICODE_PROPERTIES
        .iter()
        .find(|(alias, _)| *alias == name)
        .map_or("", |(_, canonical)| canonical)
}

